mod wave_warp {
//! Wave Warp fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
pub fn cases()->Vec<serde_json::Value>{
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for tick in [-1250000i64,-500001,-1,0,1,125000,500000] {for direction in [-45.0,90.0,720.0] {for (height,width,speed) in [(0.0,1.0,1.0),(10.0,40.0,1.0),(-10.0,4.0,-1.0),(4000.0,4000.0,100.0)] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<[f32;4]>=rgba.chunks_exact(4).map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let mut image=Image{w,h,px:input.iter().flatten().copied().collect()};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="wave_warp").unwrap().instance();
  effect.params.insert("height".into(),Param::new(ParamValue::Float(height)));
  effect.params.insert("width".into(),Param::new(ParamValue::Float(width)));
  effect.params.insert("direction".into(),Param::new(ParamValue::Float(direction)));
  effect.params.insert("speed".into(),Param::new(ParamValue::Float(speed)));
  let cx=FxCtx{t:filmcraft_time::Tick(tick as i64),px_scale:1.0,seconds:tick as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"effect":"wave_warp","localTick":tick,"parameters":{"height":height,"width":width,"direction":direction,"speed":speed},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}}
 cases
}
}
